}
@keyframes floor-pulse {
  0%, 100% { opacity: 0.6; box-shadow: 0 0 0 0 oklch(0.55 0.18 250 / 0.6); }
  50% { opacity: 1; box-shadow: 0 0 0 6px oklch(0.55 0.18 250 / 0); }
}
