  font-weight: 600;
}
.csfloat-quicktoggle .csfloat-quicktoggle-icon {
  font-size: 11px;
  opacity: 0.8;
}
.csfloat-quicktoggle.active .csfloat-quicktoggle-icon {
  opacity: 1;
}
.csfloat-quicktoggle .csfloat-quicktoggle-count {
  font-family: var(--mono);
  font-size: 9px;
  color: var(--ink-4);
  margin-left: 2px;
  font-variant-numeric: tabular-nums;
}
.csfloat-quicktoggle.active .csfloat-quicktoggle-count {
  color: oklch(0.78 0.18 250);
}

/* CSFloat-1:1: sort dropdown anchored on the right of results-bar. */
.csfloat-sort {
  margin-left: auto;
  display: inline-flex;
  align-items: center;
  gap: 6px;
}
.csfloat-sort-label {
  font-family: var(--mono);
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--ink-4);
}
.csfloat-sort-trigger {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 5px 10px;
  background: var(--bg-1);
  border: 1px solid var(--line);
  border-radius: 6px;
  font-size: 12px;
  font-weight: 500;
  color: var(--ink-1);
  cursor: pointer;
  transition: background 120ms ease, border-color 120ms ease;
}
.csfloat-sort-trigger:hover {
  background: var(--bg-2);
  border-color: var(--line-2);
}
.csfloat-sort-trigger::after {
  content: "▾";
  font-size: 9px;
  color: var(--ink-3);
  margin-left: 4px;
}

/* CSFloat-1:1: view toggle — grid view vs list view. */
.csfloat-view-toggle {
  display: inline-flex;
  background: var(--bg-2);
  border: 1px solid var(--line);
  border-radius: 6px;
  padding: 2px;
}
.csfloat-view-toggle-btn {
  width: 28px;
  height: 24px;
  background: transparent;
  border: none;
  color: var(--ink-3);
  font-size: 13px;
