}
.csfloat-list-item-grid-info {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
}
.csfloat-list-item-grid-name {
  font-size: 13px;
  font-weight: 500;
  color: var(--ink-1);
  margin: 0;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.csfloat-list-item-grid-meta {
  font-family: var(--mono);
  font-size: 10px;
  color: var(--ink-3);
