}

/* CSFloat-1:1: button with shadow (premium feel). */
.csfloat-shadow-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 10px 18px;
  background: var(--cta);
  color: oklch(0.98 0 0);
  border: 1px solid var(--cta);
  border-radius: 8px;
  font-size: 13px;
  font-weight: 600;
