  left: -3px;
  margin: -3px 0 0;
  border-top-color: transparent;
  border-right-color: var(--ink-1);
}
.csfloat-tip.is-left > .csfloat-tip-bubble {
  bottom: 50%;
  left: auto;
  right: calc(100% + 6px);
  transform: translateY(50%);
}
.csfloat-tip.is-left > .csfloat-tip-bubble::after {
  top: 50%;
  left: 100%;
  margin: -3px 0 0;
  border-top-color: transparent;
  border-left-color: var(--ink-1);
}
@media (hover: none) {
