  font-size: 11px;
}
.csfloat-mkt-card-row {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 8px;
}
.csfloat-mkt-card-price {
  font: 700 16px/1 var(--mono);
  color: var(--ink-1);
  font-feature-settings: "tnum";
  letter-spacing: -0.015em;
}
.csfloat-mkt-card-price::before {
  content: '$';
  font-size: 11px;
  color: var(--ink-3);
  margin-right: 1px;
  font-weight: 500;
  vertical-align: top;
}
.csfloat-mkt-card-meta {
  font: 400 10px/1 var(--mono);
  color: var(--ink-4);
  font-feature-settings: "tnum";
  letter-spacing: 0.02em;
  display: inline-flex;
  align-items: center;
  gap: 3px;
}
.csfloat-mkt-card-float {
  font-family: var(--mono);
  color: var(--ink-3);
}
.csfloat-mkt-card-bid {
  display: inline-flex;
  align-items: center;
  gap: 3px;
  font: 500 10px/1 var(--ui);
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: var(--cta);
}
.csfloat-mkt-card-bid::before {
  content: '';
  width: 5px;
  height: 5px;
  border-radius: 999px;
  background: currentColor;
  box-shadow: 0 0 4px currentColor;
}
/* END market grid + market card */

/* CSFloat-1:1: list-mode item row — alternative to grid card */
.csfloat-mkt-row {
  display: grid;
  grid-template-columns: 56px 1fr auto auto;
  gap: 14px;
  align-items: center;
  padding: 12px 14px;
  background: var(--bg-1);
  border: 1px solid var(--line);
  border-radius: 8px;
  cursor: pointer;
  transition: border-color 140ms cubic-bezier(0.2, 0.8, 0.2, 1), background 140ms;
}
.csfloat-mkt-row:hover {
  border-color: var(--line-2);
  background: var(--bg-2);
}
.csfloat-mkt-row-img {
  width: 56px;
  height: 56px;
  background: var(--bg-2);
  border: 1px solid var(--line);
  border-radius: 6px;
  padding: 6px;
  flex: 0 0 56px;
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
}
.csfloat-mkt-row-img > img {
  max-width: 100%;
  max-height: 100%;
  object-fit: contain;
}
.csfloat-mkt-row-img-rarity {
  position: absolute;
  bottom: 2px;
  left: 2px;
  width: 10px;
  height: 2px;
  border-radius: 1px;
  background: var(--ink-3);
}
.csfloat-mkt-row-info {
  display: flex;
  flex-direction: column;
  gap: 4px;
  min-width: 0;
}
.csfloat-mkt-row-name {
  font: 600 13px/1.3 var(--ui);
  color: var(--ink-1);
  letter-spacing: -0.005em;
  margin: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.csfloat-mkt-row-name > .csfloat-mkt-row-name-wear {
  color: var(--ink-3);
  font-weight: 400;
  margin-left: 4px;
  font-size: 11px;
}
.csfloat-mkt-row-meta {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font: 400 11px/1 var(--ui);
  color: var(--ink-4);
}
.csfloat-mkt-row-meta-item {
  display: inline-flex;
  align-items: center;
  gap: 3px;
  font-family: var(--mono);
  font-feature-settings: "tnum";
  color: var(--ink-3);
  letter-spacing: 0.01em;
}
.csfloat-mkt-row-tags {
  display: inline-flex;
  gap: 4px;
}
.csfloat-mkt-row-price {
  font: 700 16px/1 var(--mono);
  color: var(--ink-1);
  font-feature-settings: "tnum";
  letter-spacing: -0.015em;
  text-align: right;
}
.csfloat-mkt-row-price::before {
  content: '$';
  font-size: 11px;
  color: var(--ink-3);
  margin-right: 1px;
