  border-color: rgba(52, 211, 153, 0.3);
}
.csfloat-kyc.is-pending {
  border-color: rgba(251, 191, 36, 0.3);
  background: rgba(251, 191, 36, 0.04);
}
.csfloat-kyc.is-pending .csfloat-kyc-icon {
  background: rgba(251, 191, 36, 0.18);
