}
.csfloat-hero-product-img {
  position: relative;
  z-index: 1;
  width: 100%;
  aspect-ratio: 1.4;
  background: var(--bg);
  border: 1px solid var(--line);
  border-radius: 12px;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
}
.csfloat-hero-product-img > img {
  max-width: 100%;
  max-height: 100%;
  object-fit: contain;
  filter: drop-shadow(0 16px 32px rgba(0, 0, 0, 0.5)) drop-shadow(0 0 32px rgba(59, 130, 246, 0.15));
  transition: transform 320ms cubic-bezier(0.2, 0.8, 0.2, 1);
}
.csfloat-hero-product:hover .csfloat-hero-product-img > img { transform: scale(1.05); }
.csfloat-hero-product-info {
  position: relative;
  z-index: 1;
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.csfloat-hero-product-name {
  font: 700 18px/1.25 var(--ui);
  color: var(--ink-1);
  letter-spacing: -0.02em;
  margin: 0;
}
.csfloat-hero-product-meta {
  display: inline-flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
  font: 400 12px/1.4 var(--mono);
  color: var(--ink-3);
  font-feature-settings: "tnum";
}
.csfloat-hero-product-foot {
  position: relative;
  z-index: 1;
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 8px;
  margin-top: 4px;
  padding-top: 12px;
  border-top: 1px dashed var(--line);
}
.csfloat-hero-product-price {
  font: 700 24px/1 var(--mono);
  color: var(--ink-1);
  font-feature-settings: "tnum";
  letter-spacing: -0.025em;
}
.csfloat-hero-product-price::before {
  content: '$';
  font-size: 14px;
  color: var(--ink-3);
  margin-right: 1px;
  font-weight: 500;
  vertical-align: top;
}
.csfloat-hero-product-action { flex: 0 0 auto; }
@media (prefers-reduced-motion: reduce) {
  .csfloat-hero-product-tag::before { animation: none; }
}
/* END spot stat + hero product */

/* CSFloat-1:1: market browse rail — for left-side persistent filter & nav */
.csfloat-browse-rail {
  display: flex;
  flex-direction: column;
  gap: 16px;
  width: 240px;
  flex: 0 0 240px;
}
.csfloat-browse-rail-section {
  background: var(--bg-1);
  border: 1px solid var(--line);
  border-radius: 10px;
  padding: 14px 16px;
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.csfloat-browse-rail-section-title {
  font: 600 11px/1 var(--ui);
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--ink-3);
  margin: 0;
  display: inline-flex;
  align-items: center;
  gap: 6px;
}
.csfloat-browse-rail-section-title-count {
  font: 500 10px/1 var(--mono);
  color: var(--ink-4);
  font-feature-settings: "tnum";
}
.csfloat-browse-rail-section-body {
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.csfloat-browse-rail-link {
  display: grid;
  grid-template-columns: auto 1fr auto;
  gap: 8px;
  align-items: center;
  padding: 6px 8px;
  border-radius: 5px;
  font: 500 12px/1 var(--ui);
  color: var(--ink-3);
  letter-spacing: -0.005em;
  text-decoration: none;
  cursor: pointer;
  transition: background 100ms ease, color 100ms ease;
}
.csfloat-browse-rail-link:hover {
  background: var(--bg-2);
  color: var(--ink-1);
}
.csfloat-browse-rail-link.is-active {
  background: rgba(59, 130, 246, 0.08);
  color: var(--cta);
}
.csfloat-browse-rail-link-icon {
  width: 14px;
  height: 14px;
  flex: 0 0 14px;
  color: currentColor;
  opacity: 0.85;
}
.csfloat-browse-rail-link-name {
  flex: 1 1 auto;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.csfloat-browse-rail-link-count {
  font: 500 10px/1 var(--mono);
  color: var(--ink-4);
  font-feature-settings: "tnum";
}
.csfloat-browse-rail-link.is-active .csfloat-browse-rail-link-count { color: var(--cta); }
@media (max-width: 1100px) {
  .csfloat-browse-rail { width: 100%; flex: none; }
}

/* CSFloat-1:1: market browse layout — rail + main */
.csfloat-browse-layout {
  display: grid;
  grid-template-columns: 240px 1fr;
  gap: 24px;
  align-items: start;
}
@media (max-width: 1100px) {
  .csfloat-browse-layout {
    grid-template-columns: 1fr;
    gap: 16px;
  }
}

/* CSFloat-1:1: section divider chip — for breaking up content with optional label */
.csfloat-divide-chip {
  display: flex;
  align-items: center;
  gap: 12px;
  margin: 24px 0;
}
.csfloat-divide-chip::before,
.csfloat-divide-chip::after {
  content: '';
  flex: 1 1 auto;
  height: 1px;
  background: var(--line);
}
.csfloat-divide-chip-label {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 4px 10px;
  background: var(--bg-2);
  border: 1px solid var(--line);
  border-radius: 999px;
  font: 600 10px/1 var(--ui);
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--ink-3);
}
.csfloat-divide-chip-label-icon {
  width: 10px;
  height: 10px;
  color: currentColor;
  opacity: 0.7;
}
.csfloat-divide-chip.is-cta .csfloat-divide-chip-label {
  color: var(--cta);
  border-color: rgba(59, 130, 246, 0.3);
  background: rgba(59, 130, 246, 0.08);
}
.csfloat-divide-chip.is-thick::before,
.csfloat-divide-chip.is-thick::after { height: 2px; }
.csfloat-divide-chip.is-tight { margin: 12px 0; }
.csfloat-divide-chip.is-loose { margin: 36px 0; }
/* END browse rail + browse layout + divide chip */

/* CSFloat-1:1: deal blob — for offering screen */
.csfloat-deal-blob {
  position: relative;
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  gap: 16px;
  align-items: center;
  padding: 18px 22px;
  background: linear-gradient(135deg, var(--bg-2), var(--bg-1));
  border: 1px solid var(--line);
  border-radius: 14px;
}
.csfloat-deal-blob.is-active {
  border-color: var(--cta);
  background: linear-gradient(135deg, rgba(59, 130, 246, 0.04), var(--bg-1));
}
.csfloat-deal-blob-side {
  display: flex;
  flex-direction: column;
  gap: 8px;
  min-width: 0;
}
.csfloat-deal-blob-side.is-them { align-items: flex-end; text-align: right; }
.csfloat-deal-blob-side-handle {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font: 600 12px/1 var(--ui);
  color: var(--ink-1);
  letter-spacing: -0.005em;
}
.csfloat-deal-blob-side.is-them .csfloat-deal-blob-side-handle { flex-direction: row-reverse; }
.csfloat-deal-blob-side-handle-avatar {
  width: 22px;
  height: 22px;
  border-radius: 999px;
  background: var(--bg-3);
  flex: 0 0 22px;
  object-fit: cover;
}
.csfloat-deal-blob-side-items {
  display: inline-flex;
  align-items: center;
  gap: 4px;
}
.csfloat-deal-blob-side.is-them .csfloat-deal-blob-side-items { flex-direction: row-reverse; }
.csfloat-deal-blob-side-item {
  width: 36px;
  height: 36px;
  border-radius: 5px;
  background: var(--bg);
  border: 1px solid var(--line);
  padding: 4px;
  display: flex;
  align-items: center;
  justify-content: center;
}
.csfloat-deal-blob-side-item > img { max-width: 100%; max-height: 100%; object-fit: contain; }
.csfloat-deal-blob-side-more {
  width: 36px;
  height: 36px;
  border-radius: 5px;
  background: var(--bg);
  border: 1px dashed var(--line-2);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font: 600 11px/1 var(--mono);
  color: var(--ink-3);
  font-feature-settings: "tnum";
}
.csfloat-deal-blob-side-amt {
  font: 700 16px/1 var(--mono);
  color: var(--ink-1);
  font-feature-settings: "tnum";
  letter-spacing: -0.015em;
}
.csfloat-deal-blob-side-amt::before {
  content: '$';
  font-size: 11px;
  color: var(--ink-3);
  margin-right: 1px;
  font-weight: 500;
  vertical-align: top;
}
.csfloat-deal-blob-arrow {
  width: 36px;
  height: 36px;
  border-radius: 999px;
  background: var(--bg-3);
  border: 1px solid var(--line);
  color: var(--ink-3);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 36px;
  position: relative;
}
.csfloat-deal-blob-arrow::before,
.csfloat-deal-blob-arrow::after {
  content: '';
  position: absolute;
}
.csfloat-deal-blob-arrow::before {
  width: 8px;
  height: 8px;
  border-right: 1.5px solid currentColor;
  border-top: 1.5px solid currentColor;
  transform: rotate(45deg);
  right: 8px;
  top: calc(50% - 4px);
}
.csfloat-deal-blob-arrow::after {
  width: 8px;
  height: 8px;
  border-left: 1.5px solid currentColor;
  border-bottom: 1.5px solid currentColor;
  transform: rotate(45deg);
  left: 8px;
  top: calc(50% - 4px);
}
.csfloat-deal-blob.is-active .csfloat-deal-blob-arrow {
  background: rgba(59, 130, 246, 0.12);
  border-color: var(--cta);
  color: var(--cta);
}
@media (max-width: 720px) {
  .csfloat-deal-blob {
    grid-template-columns: 1fr;
    gap: 10px;
  }
  .csfloat-deal-blob-side.is-them {
    align-items: flex-start;
    text-align: left;
  }
  .csfloat-deal-blob-side.is-them .csfloat-deal-blob-side-handle,
  .csfloat-deal-blob-side.is-them .csfloat-deal-blob-side-items {
    flex-direction: row;
  }
  .csfloat-deal-blob-arrow { transform: rotate(90deg); width: 28px; height: 28px; flex: 0 0 28px; }
}

/* CSFloat-1:1: hero meta strip — sits above hero CTA */
.csfloat-hero-meta-strip {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 16px;
  padding: 12px 16px;
  background: var(--bg-1);
  border: 1px solid var(--line);
  border-radius: 999px;
  font: 500 12px/1 var(--ui);
  color: var(--ink-3);
  letter-spacing: -0.005em;
}
.csfloat-hero-meta-strip-item {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}
.csfloat-hero-meta-strip-item-mono {
  font-family: var(--mono);
  font-feature-settings: "tnum";
  font-weight: 600;
  color: var(--ink-1);
}
.csfloat-hero-meta-strip-item-icon {
  width: 14px;
  height: 14px;
  color: var(--cta);
}
.csfloat-hero-meta-strip-divider {
  width: 1px;
