  font: 500 12px/1 var(--ui);
}
.csfloat-shortcut-card-x:hover {
  background: var(--bg-2);
  color: var(--ink-1);
}
@media (prefers-reduced-motion: reduce) {
  .csfloat-shortcut-card { animation: none; }
}

