}
.csfloat-insight-chart-title {
  font: 600 13px/1.3 var(--ui);
  letter-spacing: -0.005em;
  color: var(--ink-1);
  margin: 0;
}
.csfloat-insight-chart-stamp {
  font: 400 11px/1 var(--mono);
  color: var(--ink-4);
  font-feature-settings: "tnum";
  letter-spacing: 0.02em;
