}
.csfloat-action-img-card-info {
  display: flex;
  flex-direction: column;
  gap: 4px;
  min-width: 0;
}
.csfloat-action-img-card-name {
  font: 600 13px/1.3 var(--ui);
  color: var(--ink-1);
  letter-spacing: -0.005em;
