}
@media (prefers-reduced-motion: reduce) {
  .csfloat-status-tag.is-pulse::before { animation: none; }
}
.csfloat-status-tag-mono {
  font-family: var(--mono);
  font-feature-settings: "tnum";
  font-weight: 700;
  letter-spacing: 0;
}

/* CSFloat-1:1: chunked badge with right action */
.csfloat-badge-act {
