}
.csfloat-trade-stat-val {
  font: 700 14px/1 var(--mono);
  color: var(--ink-1);
  font-feature-settings: "tnum";
  letter-spacing: -0.005em;
}
.csfloat-trade-stat-val.is-currency::before {
  content: '$';
