  background-color: rgba(30, 32, 38, 0.55) !important;
  border: none !important;
  border-radius: 50% !important;
  color: rgba(255, 255, 255, 0.85) !important;
  cursor: pointer !important;
  z-index: 3 !important;
  backdrop-filter: blur(6px) !important;
  -webkit-backdrop-filter: blur(6px) !important;
  font-size: 14px !important;
  font-weight: 600 !important;
  transition: background-color 0.15s ease, color 0.15s ease !important;
  opacity: 0 !important;
}
.grid-card:hover .grid-star,
.grid-card:hover .grid-cart-btn,
.grid-card .grid-star.on,
.grid-card .grid-cart-btn.in {
  opacity: 1 !important;
}
.grid-card .grid-star {
  top: 6px !important;
  right: 6px !important;
}
.grid-card .grid-cart-btn {
  top: 6px !important;
  right: 40px !important;
}
.grid-card .grid-star.on {
  background-color: rgba(235, 75, 75, 0.85) !important;
  color: #fff !important;
}
.grid-card .grid-cart-btn.in {
