  padding: 8px 0 !important;
  box-shadow:
    0 5px 5px -3px rgba(0, 0, 0, 0.2),
    0 8px 10px 1px rgba(0, 0, 0, 0.14),
    0 3px 14px 2px rgba(0, 0, 0, 0.12) !important;
}
.dropdown-panel .dropdown-option,
.dropdown-panel li,
.csfloat-dropdown-panel li,
.custom-select-panel li,
.select-panel li,
.mat-mdc-select-panel .mat-mdc-option,
[class*="dropdown-options"] [class*="option"],
[class*="select-options"] [class*="option"] {
  font-family: Roboto, "Helvetica Neue", -apple-system, BlinkMacSystemFont, sans-serif !important;
  font-size: 16px !important;
  letter-spacing: 0.5px !important;
  color: rgba(255, 255, 255, 0.87) !important;
  min-height: 48px !important;
  padding: 0 16px !important;
  display: flex !important;
  align-items: center !important;
  cursor: pointer !important;
  transition: background-color 120ms ease !important;
}
.dropdown-panel .dropdown-option:hover,
.dropdown-panel li:hover,
.csfloat-dropdown-panel li:hover,
.custom-select-panel li:hover,
.select-panel li:hover,
.mat-mdc-select-panel .mat-mdc-option:hover,
[class*="dropdown-options"] [class*="option"]:hover,
[class*="select-options"] [class*="option"]:hover {
  background-color: rgba(255, 255, 255, 0.04) !important;
}
/* END CSFLOAT-1:1 PARITY ship #1402 */

/* CSFLOAT-1:1 PARITY ship #1403 — checkbox sizing matches csfloat
   .mat-mdc-checkbox: 18x18 box, 2px radius, brand blue accent when
   checked, subtle border. Measured on csfloat filter checkboxes:
   18px box, accent-color matches brand blue (#40a0fe). */
input[type="checkbox"] {
  width: 18px !important;
  height: 18px !important;
  accent-color: #40a0fe !important;
  cursor: pointer !important;
  border-radius: 2px !important;
  margin: 0 !important;
  flex-shrink: 0 !important;
  vertical-align: middle !important;
}
/* csfloat label-pair pattern: 8px gap between checkbox and label text */
.filter-option,
.csfloat-filter-checkbox,
.checkbox-row,
label:has(> input[type="checkbox"]),
label:has(> input[type="checkbox"] + *) {
  display: inline-flex !important;
  align-items: center !important;
  gap: 8px !important;
  cursor: pointer !important;
  font-family: Roboto, "Helvetica Neue", -apple-system, BlinkMacSystemFont, sans-serif !important;
  font-size: 14px !important;
  letter-spacing: 0.25px !important;
  color: rgba(255, 255, 255, 0.87) !important;
}
/* END CSFLOAT-1:1 PARITY ship #1403 */

/* CSFLOAT-1:1 PARITY ship #1404 — radio button sizing matches csfloat
   .mat-mdc-radio-button native input: 20x20, 50% radius (full circle),
   brand blue accent when selected. Measured on csfloat radio groups. */
input[type="radio"] {
  width: 20px !important;
  height: 20px !important;
  accent-color: #40a0fe !important;
  cursor: pointer !important;
  border-radius: 50% !important;
  margin: 0 !important;
  flex-shrink: 0 !important;
  vertical-align: middle !important;
}
.radio-row,
.radio-option,
label:has(> input[type="radio"]),
label:has(> input[type="radio"] + *) {
  display: inline-flex !important;
  align-items: center !important;
  gap: 8px !important;
  cursor: pointer !important;
  font-family: Roboto, "Helvetica Neue", -apple-system, BlinkMacSystemFont, sans-serif !important;
  font-size: 14px !important;
  letter-spacing: 0.25px !important;
  color: rgba(255, 255, 255, 0.87) !important;
}
/* END CSFLOAT-1:1 PARITY ship #1404 */

/* CSFLOAT-1:1 PARITY ship #1405 — toggle switch styling matches csfloat
   .mat-mdc-slide-toggle: 36x20 track, 16px thumb, brand-blue track when
   on, neutral grey when off, smooth 200ms transition. Measured on
   csfloat slide-toggle: track 36x20, thumb 16x16 with 2px inset. */
[role="switch"],
.toggle-switch,
.csfloat-toggle,
.slide-toggle,
.mat-mdc-slide-toggle .mdc-switch {
  position: relative !important;
  display: inline-flex !important;
  align-items: center !important;
  width: 36px !important;
  height: 20px !important;
  background: rgba(255, 255, 255, 0.16) !important;
  border-radius: 10px !important;
  border: 1px solid rgba(255, 255, 255, 0.12) !important;
  cursor: pointer !important;
  transition: background-color 200ms ease, border-color 200ms ease !important;
  vertical-align: middle !important;
  flex-shrink: 0 !important;
}
[role="switch"][aria-checked="true"],
.toggle-switch.on,
.toggle-switch[data-on="true"],
.csfloat-toggle.on,
.slide-toggle.on,
.mat-mdc-slide-toggle.mat-mdc-slide-toggle-checked .mdc-switch {
  background: #40a0fe !important;
  border-color: #40a0fe !important;
}
[role="switch"]::before,
.toggle-switch::before,
.csfloat-toggle::before,
.slide-toggle::before {
  content: "" !important;
  position: absolute !important;
  top: 50% !important;
  left: 2px !important;
  width: 16px !important;
  height: 16px !important;
  background: #ffffff !important;
  border-radius: 50% !important;
  transform: translateY(-50%) !important;
  transition: left 200ms ease, transform 200ms ease !important;
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.4) !important;
}
[role="switch"][aria-checked="true"]::before,
.toggle-switch.on::before,
.toggle-switch[data-on="true"]::before,
.csfloat-toggle.on::before,
.slide-toggle.on::before {
  left: 18px !important;
}
/* END CSFLOAT-1:1 PARITY ship #1405 */

/* CSFLOAT-1:1 PARITY ship #1406
   Right-rail stat-panel container (.modal-stat-box) — measure-and-match the
   csfloat mat-card surface used in the item detail page right rail.
   csfloat: bg #1f2128, 1px solid rgba(255,255,255,0.06), radius 8px, padding
   16px 18px, no shadow on the inner panel. Earlier overrides drifted
   to #181a20/12px/14px — restore to spec. */
.modal-stat-box,
.full-page-mode .modal-stat-box,
.site-root.full-page-mode .modal-stat-box {
  background-color: #1f2128 !important;
  border: 1px solid rgba(255, 255, 255, 0.06) !important;
  border-radius: 8px !important;
  padding: 16px 18px !important;
  box-shadow: none !important;
  display: flex !important;
  flex-direction: column !important;
  gap: 6px !important;
  min-height: 76px !important;
  transition: border-color 0.15s ease, background-color 0.15s ease !important;
}
.modal-stat-box:hover,
.full-page-mode .modal-stat-box:hover {
  border-color: rgba(255, 255, 255, 0.10) !important;
  background-color: #22242c !important;
}
/* END CSFLOAT-1:1 PARITY ship #1406 */

/* CSFLOAT-1:1 PARITY ship #1407
   Eyebrow caption labels (.modal-stat-label) — small uppercase text above the
   big stat number. csfloat: 11px, weight 500, letter-spacing 0.6px, color
   rgba(255,255,255,0.55), text-transform uppercase, line-height 1.2. */
.modal-stat-label,
.full-page-mode .modal-stat-label,
.site-root.full-page-mode .modal-stat-label {
  font-size: 11px !important;
  font-weight: 500 !important;
  letter-spacing: 0.6px !important;
  text-transform: uppercase !important;
  line-height: 1.2 !important;
  color: rgba(255, 255, 255, 0.55) !important;
  margin: 0 0 2px 0 !important;
  white-space: nowrap !important;
  overflow: hidden !important;
  text-overflow: ellipsis !important;
}
/* END CSFLOAT-1:1 PARITY ship #1407 */

/* CSFLOAT-1:1 PARITY ship #1408
   Stat value (.modal-stat-val) — big number under the eyebrow. csfloat:
   20px, weight 600, color #fff, line-height 1.25, tabular figures so
   adjacent values line up. The accent variant (used for Listing Price) gets
   the brand blue #40a0fe. Delta chip is 11px, weight 600, padding 2px 6px,
   radius 4px, green for positive (#27c483 on rgba(39,196,131,0.14)) and red
   for negative (#ff4d6e on rgba(255,77,110,0.14)). */
.modal-stat-val,
.full-page-mode .modal-stat-val,
.site-root.full-page-mode .modal-stat-val {
  font-size: 20px !important;
  font-weight: 600 !important;
  line-height: 1.25 !important;
  color: #ffffff !important;
  font-feature-settings: "tnum" 1, "lnum" 1 !important;
  font-variant-numeric: tabular-nums !important;
  margin: 0 !important;
  letter-spacing: -0.1px !important;
}
.modal-stat-val.accent,
.full-page-mode .modal-stat-val.accent {
  color: #40a0fe !important;
}
.modal-stat-val .delta,
.modal-stat-val .delta-chip,
.modal-stat-val .stat-delta,
.full-page-mode .modal-stat-val .delta {
  display: inline-flex !important;
  align-items: center !important;
  font-size: 11px !important;
  font-weight: 600 !important;
  padding: 2px 6px !important;
  border-radius: 4px !important;
  line-height: 1.2 !important;
  letter-spacing: 0 !important;
  vertical-align: middle !important;
}
.modal-stat-val .delta.up,
.modal-stat-val .delta-chip.up,
.modal-stat-val .stat-delta.up,
.modal-stat-val .delta[data-dir="up"] {
  color: #27c483 !important;
  background-color: rgba(39, 196, 131, 0.14) !important;
}
.modal-stat-val .delta.down,
.modal-stat-val .delta-chip.down,
.modal-stat-val .stat-delta.down,
.modal-stat-val .delta[data-dir="down"] {
  color: #ff4d6e !important;
  background-color: rgba(255, 77, 110, 0.14) !important;
}
.modal-stat-val .delta.flat,
.modal-stat-val .delta-chip.flat {
  color: rgba(255, 255, 255, 0.55) !important;
  background-color: rgba(255, 255, 255, 0.06) !important;
}
/* END CSFLOAT-1:1 PARITY ship #1408 */

/* CSFLOAT-1:1 PARITY ship #1409
   Detail-row tables — key/value rows that appear in the item modal body and
   stall sheets. csfloat formats these as a 2-column row: label on the left
   in eyebrow style, value on the right in white 13px tabular. Border-bottom
   1px rgba white .04 except last row. Vertical padding 8px. */
.modal-detail-row,
.detail-row,
.modal-kv-row,
.full-page-mode .modal-detail-row,
.full-page-mode .detail-row {
