  border: 1px solid rgb(38, 40, 48) !important;
  border-radius: 8px !important;
  padding: 16px 20px !important;
  min-height: 64px !important;
  border-bottom: 1px solid rgb(38, 40, 48) !important;
  transition: border-color 140ms ease, background 140ms ease !important;
}
body .full-page-mode .buyorder-list > .buyorder-row:hover,
body .full-page-mode .buyorder-list > .buy-order-row:hover,
