     doesn't pin to the top awkwardly when the user is scrolling the long
     mobile single-column layout. */
  body .modal.item-page .item-rail,
  body .modal.item-page .modal-grid > :nth-child(2),
  body .modal.item-page .item-modal-grid > :nth-child(2) {
    position: static !important;
    top: auto !important;
    max-height: none !important;
  }
}
