  letter-spacing: 0.10em !important;
  text-transform: uppercase !important;
  background: rgba(20, 24, 32, 0.72) !important;
  border: 1px solid rgba(255, 255, 255, 0.10) !important;
  border-radius: 4px !important;
  color: rgba(220, 226, 240, 0.92) !important;
  backdrop-filter: blur(6px) !important;
  -webkit-backdrop-filter: blur(6px) !important;
  line-height: 1.4 !important;
  z-index: 4 !important;
  pointer-events: none !important;
  user-select: none !important;
}
.csfloat-gallery-main .item-tag-overlay.standard,
.csfloat-gallery-main [data-tag="standard"] {
  color: rgba(180, 190, 210, 0.95) !important;
  background: rgba(35, 40, 52, 0.72) !important;
}
.csfloat-gallery-main .item-tag-overlay.off-market,
.csfloat-gallery-main [data-tag="off-market"] {
  color: rgba(255, 180, 90, 0.95) !important;
  border-color: rgba(255, 180, 90, 0.22) !important;
  background: rgba(60, 35, 12, 0.72) !important;
}
/* END CSFLOAT-1:1 PARITY ship #5008 */

/* CSFLOAT-1:1 PARITY ship #5009 — thumbnail strip below main image.
   csfloat: row of 56x56 thumbnails, gap 6px, pill-rounded, bg slightly darker
