  grid-template-columns: 1fr !important;
  row-gap: 12px !important;
}
.modal.info-modal:has(> .info-modal-body > .db-controls) > .info-modal-body > .db-controls::before {
  content: "Filters" !important;
  display: block !important;
  font-size: 13px !important;
  font-weight: 700 !important;
  letter-spacing: 0.02em !important;
  color: rgb(232, 234, 240) !important;
  padding: 4px 2px 8px !important;
  border-bottom: 1px solid oklch(0.30 0.012 260) !important;
  margin-bottom: 2px !important;
}
/* END CSFLOAT-1:1 PARITY ship #6314 */
/* CSFLOAT-1:1 PARITY ship #6315 — Db results meta row sits at top of the right column at csfloat 12.5px text. Strong = item count emphasis. */
.modal.info-modal:has(> .info-modal-body > .db-controls) > .info-modal-body > .db-meta {
  font-size: 12.5px !important;
  line-height: 1.4 !important;
  padding: 4px 0 8px !important;
  color: oklch(0.74 0.010 260) !important;
  border-bottom: 1px solid oklch(0.30 0.012 260) !important;
  margin-bottom: 4px !important;
}
.modal.info-modal:has(> .info-modal-body > .db-controls) > .info-modal-body > .db-meta strong {
  font-size: 12.5px !important;
  font-weight: 700 !important;
  color: rgb(232, 234, 240) !important;
}
/* END CSFLOAT-1:1 PARITY ship #6315 */

/* CSFLOAT-1:1 PARITY ship #6700 - Toolbar refresh button base: csfloat polishes its 36x36 icon button with oklch hover/active surfaces, 1px subtle border, 0.18s ease transitions. Match the surface treatment 1:1. */
.toolbar .toolbar-refresh {
  width: 36px !important;
  height: 36px !important;
  background-color: oklch(0.2 0.009 260) !important;
  color: oklch(0.8 0.01 260) !important;
  border: 1px solid rgba(193, 206, 255, 0.12) !important;
  border-radius: 6px !important;
  padding: 0 !important;
  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
  cursor: pointer !important;
  box-shadow: none !important;
  transition: background-color 0.18s cubic-bezier(0.4, 0, 0.2, 1),
              border-color 0.18s cubic-bezier(0.4, 0, 0.2, 1),
              color 0.18s cubic-bezier(0.4, 0, 0.2, 1),
              transform 0.18s cubic-bezier(0.4, 0, 0.2, 1) !important;
  flex-shrink: 0 !important;
}
.toolbar .toolbar-refresh:hover {
  background-color: oklch(0.235 0.011 260) !important;
  border-color: rgba(193, 206, 255, 0.22) !important;
  color: oklch(0.92 0.012 260) !important;
}
.toolbar .toolbar-refresh:active {
  background-color: oklch(0.175 0.009 260) !important;
  transform: scale(0.96) !important;
}
.toolbar .toolbar-refresh:focus-visible {
  outline: 2px solid rgba(120, 168, 255, 0.55) !important;
  outline-offset: 2px !important;
}
.toolbar .toolbar-refresh:disabled {
  opacity: 0.5 !important;
  cursor: not-allowed !important;
  pointer-events: none !important;
}
/* END CSFLOAT-1:1 PARITY ship #6700 */

/* CSFLOAT-1:1 PARITY ship #6701 - Refresh icon glyph spin state: csfloat spins arrow-circle at 0.9s linear infinite while in-flight via [data-refreshing] / .is-refreshing. Match exact 16x16 SVG sizing with 1.8 stroke and provide the keyframe + hover micro-rotate. */
.toolbar .toolbar-refresh svg {
  width: 16px !important;
  height: 16px !important;
  stroke: currentColor !important;
  stroke-width: 1.8 !important;
  fill: none !important;
  stroke-linecap: round !important;
  stroke-linejoin: round !important;
  display: block !important;
  transition: transform 0.18s cubic-bezier(0.4, 0, 0.2, 1) !important;
}
.toolbar .toolbar-refresh:hover svg {
  transform: rotate(-12deg) !important;
}
@keyframes csfloatRefreshSpin {
  from { transform: rotate(0deg); }
  to   { transform: rotate(360deg); }
}
.toolbar .toolbar-refresh[data-refreshing="true"] svg,
.toolbar .toolbar-refresh.is-refreshing svg {
  animation: csfloatRefreshSpin 0.9s linear infinite !important;
  transform: none !important;
}
.toolbar .toolbar-refresh[data-refreshing="true"],
.toolbar .toolbar-refresh.is-refreshing {
  pointer-events: none !important;
  color: oklch(0.85 0.05 240) !important;
  border-color: rgba(120, 168, 255, 0.32) !important;
}
/* END CSFLOAT-1:1 PARITY ship #6701 */

/* CSFLOAT-1:1 PARITY ship #6702 - Last-updated chip "Updated 12s ago": 11.5px medium-weight muted chip with 5px green dot, 24px tall, oklch muted text, tabular nums. Spec for .toolbar-last-updated / [data-last-updated]. */
.toolbar .toolbar-last-updated,
.toolbar [data-last-updated] {
  display: inline-flex !important;
  align-items: center !important;
  gap: 4px !important;
  height: 24px !important;
  padding: 0 6px !important;
  margin-left: 4px !important;
  font-size: 11.5px !important;
  font-weight: 500 !important;
  line-height: 1 !important;
  color: oklch(0.62 0.012 260) !important;
  letter-spacing: 0.005em !important;
  white-space: nowrap !important;
  font-variant-numeric: tabular-nums !important;
  user-select: none !important;
  background: transparent !important;
  border: 0 !important;
}
.toolbar .toolbar-last-updated::before,
.toolbar [data-last-updated]::before {
  content: '' !important;
  display: inline-block !important;
  width: 5px !important;
  height: 5px !important;
  border-radius: 50% !important;
  background-color: oklch(0.7 0.13 145) !important;
  box-shadow: 0 0 6px oklch(0.7 0.13 145 / 0.45) !important;
  flex-shrink: 0 !important;
  margin-right: 2px !important;
}
.toolbar .toolbar-last-updated.is-stale,
.toolbar [data-last-updated][data-stale="true"] {
  color: oklch(0.55 0.012 260) !important;
}
.toolbar .toolbar-last-updated.is-stale::before,
.toolbar [data-last-updated][data-stale="true"]::before {
  background-color: oklch(0.65 0.13 70) !important;
  box-shadow: 0 0 6px oklch(0.65 0.13 70 / 0.45) !important;
}
/* END CSFLOAT-1:1 PARITY ship #6702 */

/* CSFLOAT-1:1 PARITY ship #6703 - Live activity ticker strip: 28px-tall horizontal marquee, rgba(27,29,36,0.8) bg, 1px subtle bottom border, 12px text, oklch muted text, fade-edge masks, 36s linear infinite scroll, hover-pause. */
.activity-ticker,
.toolbar-ticker,
[data-activity-ticker] {
