  display: flex !important;
  align-items: center !important;
  width: 100% !important;
  height: 28px !important;
  background-color: rgba(27, 29, 36, 0.8) !important;
  border-bottom: 1px solid rgba(193, 206, 255, 0.06) !important;
  overflow: hidden !important;
  font-size: 12px !important;
  line-height: 1 !important;
  color: oklch(0.72 0.011 260) !important;
  user-select: none !important;
  -webkit-mask-image: linear-gradient(to right, transparent, #000 64px, #000 calc(100% - 64px), transparent) !important;
          mask-image: linear-gradient(to right, transparent, #000 64px, #000 calc(100% - 64px), transparent) !important;
}
.activity-ticker .ticker-track,
.toolbar-ticker .ticker-track,
[data-activity-ticker] .ticker-track {
  display: inline-flex !important;
  align-items: center !important;
