}
.activity-ticker .ticker-item,
.toolbar-ticker .ticker-item,
[data-activity-ticker] .ticker-item {
  display: inline-flex !important;
  align-items: center !important;
  gap: 6px !important;
  font-size: 12px !important;
  font-weight: 500 !important;
  color: oklch(0.78 0.011 260) !important;
  letter-spacing: 0.005em !important;
}
.activity-ticker .ticker-item .ticker-dot,
.toolbar-ticker .ticker-item .ticker-dot,
[data-activity-ticker] .ticker-item .ticker-dot {
  width: 4px !important;
  height: 4px !important;
  border-radius: 50% !important;
  background-color: oklch(0.7 0.13 145) !important;
  flex-shrink: 0 !important;
}
.activity-ticker .ticker-item.is-sale .ticker-dot,
.toolbar-ticker .ticker-item.is-sale .ticker-dot,
[data-activity-ticker] .ticker-item[data-kind="sale"] .ticker-dot {
  background-color: oklch(0.7 0.13 145) !important;
}
.activity-ticker .ticker-item.is-listing .ticker-dot,
