/* CSFLOAT-1:1 PARITY ship #7102 — click pulse + toggle-on burst animation.
   Match csfloat: when a heart toggles to active it scales 1 -> 1.35 -> 1
   over 320ms with a soft elastic ease, plus a single radial burst ring that
   fades from 0 -> 1 -> 0 opacity while it expands from 0 to 28px. Active
   heart also gets a slow 1.6s ambient pulse that breathes the halo so the
   card has a subtle heartbeat once you've added it. */
@keyframes csfloat-heart-pop {
  0%   { transform: scale(1); }
  35%  { transform: scale(1.35); }
  70%  { transform: scale(0.92); }
  100% { transform: scale(1); }
}
@keyframes csfloat-heart-burst {
  0%   { transform: translate(-50%, -50%) scale(0.4); opacity: 0; }
  30%  { opacity: 0.9; }
  100% { transform: translate(-50%, -50%) scale(2.4); opacity: 0; }
}
@keyframes csfloat-heart-breathe {
  0%, 100% { box-shadow: 0 0 0 0 rgba(235, 75, 75, 0); }
  50%      { box-shadow: 0 0 0 4px rgba(235, 75, 75, 0.15); }
}
body .grid-star,
body button.grid-star,
body .item-watchlist-toggle,
body button.item-watchlist-toggle {
  position: relative !important;
}
body .grid-star::after,
body .item-watchlist-toggle::after {
  content: '' !important;
  position: absolute !important;
  top: 50% !important;
  left: 50% !important;
  width: 28px !important;
  height: 28px !important;
  border-radius: 50% !important;
  border: 2px solid rgba(235, 75, 75, 0.7) !important;
  transform: translate(-50%, -50%) scale(0.4) !important;
  opacity: 0 !important;
  pointer-events: none !important;
}
body .grid-star.on::after,
body .grid-star[aria-pressed="true"]::after,
body .item-watchlist-toggle.active::after,
body .item-watchlist-toggle[aria-pressed="true"]::after {
  animation: csfloat-heart-burst 480ms cubic-bezier(0.16, 1, 0.3, 1) !important;
}
body .grid-star.on,
body .grid-star[aria-pressed="true"],
body .item-watchlist-toggle.active,
body .item-watchlist-toggle[aria-pressed="true"] {
  animation: csfloat-heart-pop 320ms cubic-bezier(0.34, 1.56, 0.64, 1), csfloat-heart-breathe 1600ms ease-in-out 320ms infinite !important;
}
body .grid-star:active,
body button.grid-star:active,
body .item-watchlist-toggle:active,
body button.item-watchlist-toggle:active {
  transform: scale(0.88) !important;
  transition-duration: 80ms !important;
}
@media (prefers-reduced-motion: reduce) {
  body .grid-star.on,
  body .grid-star[aria-pressed="true"],
  body .item-watchlist-toggle.active,
  body .item-watchlist-toggle[aria-pressed="true"] {
    animation: none !important;
  }
  body .grid-star::after,
  body .item-watchlist-toggle::after {
    display: none !important;
  }
}
/* END CSFLOAT-1:1 PARITY ship #7102 */

/* CSFLOAT-1:1 PARITY ship #7103 — confetti burst particles on toggle-on.
   Match csfloat: a quick 6-particle radial spark at the cardinal + diagonal
   positions, each particle a 2px dot fading from 1 -> 0 opacity while the
   whole halo scales from 0.2 -> 1.0. Implemented as a single ::before with
   six layered radial-gradients so we don't need 6 elements. The animation
   gates on .on / [aria-pressed=true] so it only plays on toggle-on. */
@keyframes csfloat-heart-spark {
  0%   { opacity: 0; transform: translate(-50%, -50%) scale(0.2); }
  20%  { opacity: 1; }
  100% { opacity: 0; transform: translate(-50%, -50%) scale(1); }
}
body .grid-star::before,
body .item-watchlist-toggle::before {
  content: '' !important;
  position: absolute !important;
  top: 50% !important;
  left: 50% !important;
  width: 44px !important;
  height: 44px !important;
  border-radius: 50% !important;
  pointer-events: none !important;
  opacity: 0 !important;
  background:
    radial-gradient(circle 2px at 50% 0%,    #eb4b4b 0%, transparent 100%),
    radial-gradient(circle 2px at 93.3% 25%, #f59f3a 0%, transparent 100%),
    radial-gradient(circle 2px at 93.3% 75%, #eb4b4b 0%, transparent 100%),
    radial-gradient(circle 2px at 50% 100%,  #ffd166 0%, transparent 100%),
    radial-gradient(circle 2px at 6.7% 75%,  #eb4b4b 0%, transparent 100%),
    radial-gradient(circle 2px at 6.7% 25%,  #ff8aa2 0%, transparent 100%) !important;
  background-repeat: no-repeat !important;
  transform: translate(-50%, -50%) scale(0.2) !important;
  z-index: 1 !important;
}
body .grid-star.on::before,
body .grid-star[aria-pressed="true"]::before,
body .item-watchlist-toggle.active::before,
body .item-watchlist-toggle[aria-pressed="true"]::before {
  animation: csfloat-heart-spark 560ms cubic-bezier(0.22, 1, 0.36, 1) !important;
}
@media (prefers-reduced-motion: reduce) {
