}
.csfloat-home-tool-card.trade-up .csfloat-home-tool-card-arrow,
.csfloat-home-tool-card[data-tool="trade-up"] .csfloat-home-tool-card-arrow {
  color: oklch(0.78 0.18 60) !important;
}
.csfloat-home-tool-card.float-checker .csfloat-home-tool-card-arrow,
.csfloat-home-tool-card[data-tool="float-checker"] .csfloat-home-tool-card-arrow {
  color: oklch(0.78 0.16 230) !important;
}
/* END CSFLOAT-1:1 PARITY ship #8207 */

