.csfloat-home-tool-card:has(.tool-icon) .csfloat-home-tool-card-title {
  grid-column: 2 !important;
  grid-row: 2 !important;
}
@media (max-width: 720px) {
  .csfloat-home-tool-card.has-icon,
  .csfloat-home-tool-card:has(.tool-icon) {
    grid-template-columns: 32px 1fr !important;
