              0 8px 24px -8px rgba(0, 0, 0, 0.3) !important;
}
.cart-confirm-title {
  font-family: Roboto, "Helvetica Neue", system-ui, sans-serif !important;
  font-size: 20px !important;
  font-weight: 500 !important;
  line-height: 28px !important;
  letter-spacing: normal !important;
  color: rgb(255, 255, 255) !important;
}
.cart-confirm-sub {
  font-size: 13px !important;
  font-weight: 400 !important;
  color: rgba(255, 255, 255, 0.65) !important;
  line-height: 1.5 !important;
}
.cart-confirm-row {
  font-size: 13px !important;
  color: rgba(255, 255, 255, 0.85) !important;
  border-bottom: 1px solid oklch(0.27 0.011 260) !important;
}
.cart-confirm-total {
  border-top: 1px solid oklch(0.36 0.014 260) !important;
}
.cart-confirm-total-label {
  font-size: 14px !important;
  font-weight: 500 !important;
  color: rgb(255, 255, 255) !important;
}
.cart-confirm-total-hint {
