/* CSFLOAT-1:1 PARITY ship #10203 - Active filter chip strip layout +
   slide-in/out animation. Strip uses 8px gap to match csfloat's
   inter-toggle spacing; chips animate from -8px translateX with a
   140ms ease curve consistent with csfloat's standard transitions. */
.cf-active-chips {
  display: flex !important;
  flex-wrap: wrap !important;
  gap: 8px !important;
  align-items: center !important;
}
.cf-active-chips .cf-ac,
.cf-ac {
  animation: cf-ac-slide-in 180ms cubic-bezier(0.2, 0.8, 0.2, 1) both !important;
}
.cf-active-chips .cf-ac.removing,
.cf-ac.removing {
  animation: cf-ac-slide-out 140ms cubic-bezier(0.4, 0, 1, 1) both !important;
  pointer-events: none !important;
}
@keyframes cf-ac-slide-in {
  from { opacity: 0; transform: translateX(-8px) scale(0.96); }
  to   { opacity: 1; transform: translateX(0) scale(1); }
}
@keyframes cf-ac-slide-out {
  from { opacity: 1; transform: translateX(0) scale(1); max-width: 200px; }
  to   { opacity: 0; transform: translateX(8px) scale(0.92); max-width: 0; padding-left: 0; padding-right: 0; margin-right: -8px; border-width: 0; }
}
/* END CSFLOAT-1:1 PARITY ship #10203 */

