  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
  gap: 5px !important;
  height: 28px !important;
  padding: 0 12px !important;
  background: var(--bg-1) !important;
  border: 1px dashed var(--line-2) !important;
  border-radius: 4px !important;
  color: var(--ink-3) !important;
  font: 500 10px/1 'JetBrains Mono', 'Roboto Mono', ui-monospace, monospace !important;
  letter-spacing: 0.12em !important;
  text-transform: uppercase !important;
  cursor: pointer !important;
  transition: color 110ms ease, border-color 110ms ease, background 110ms ease !important;
}
.loadout-add-btn:hover {
  color: var(--ink) !important;
  border-color: var(--ink-4) !important;
  background: var(--bg-2) !important;
}
.loadout-add-btn:focus-visible {
  outline: 1px solid var(--ink-4) !important;
  outline-offset: 2px !important;
}
.loadout-picker > .loadout-add-btn {
  display: flex !important;
  width: 100% !important;
  margin-top: 8px !important;
  border-style: solid !important;
  border-color: var(--line) !important;
}
.loadout-picker > .loadout-add-btn:hover {
  border-color: var(--line-2) !important;
}
/* END CSFLOAT-1:1 PARITY ship #10403 */

/* CSFLOAT-1:1 PARITY ship #10404 - empty-slot host bounds + empty-list state.
   csfloat empty slot has 96px min-height to match a filled slot, the picker
