  padding: 0 !important;
  margin-top: auto !important;
  font-family: var(--mono) !important;
  font-style: normal !important;
  font-size: 12px !important;
  color: var(--ink-4) !important;
}
.loadout-slot-empty:has(> .loadout-picker) {
  min-height: 0 !important;
}
.loadout-slot:has(> .loadout-slot-empty > .loadout-picker) {
  min-height: 96px !important;
  padding: 10px !important;
  border-style: solid !important;
  border-color: var(--line-2) !important;
  background: var(--bg) !important;
}
.loadout-picker-list:empty {
  min-height: 32px !important;
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
  font: 500 11px/1 'Inter', 'Roboto', system-ui, sans-serif !important;
  color: var(--ink-4) !important;
  letter-spacing: -0.005em !important;
}
/* END CSFLOAT-1:1 PARITY ship #10404 */

