  padding: 0 !important;
  background: transparent !important;
  border: 0 !important;
  border-radius: 0 !important;
  font-family: Roboto, "Helvetica Neue", sans-serif !important;
  font-size: 14px !important;
  line-height: 20px !important;
  letter-spacing: 0.25px !important;
  color: rgba(255, 255, 255, 0.87) !important;
  white-space: nowrap !important;
}
.stall-rating::before,
.stall-rating-chip::before,
.profile-rating::before,
.seller-rating-row::before {
  content: '' !important;
  display: inline-block !important;
  width: 16px !important;
  height: 16px !important;
  background-color: #fbbf24 !important;
  -webkit-mask: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24'><path d='M12 17.27L18.18 21l-1.64-7.03L22 9.24l-7.19-.61L12 2 9.19 8.63 2 9.24l5.46 4.73L5.82 21z'/></svg>") center / contain no-repeat !important;
          mask: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24'><path d='M12 17.27L18.18 21l-1.64-7.03L22 9.24l-7.19-.61L12 2 9.19 8.63 2 9.24l5.46 4.73L5.82 21z'/></svg>") center / contain no-repeat !important;
  flex: 0 0 16px !important;
  vertical-align: middle !important;
}
.stall-rating .rating-value,
.stall-rating-chip .rating-value,
.profile-rating .rating-value,
.seller-rating-row .rating-value {
  font-weight: 500 !important;
  color: rgba(255, 255, 255, 0.87) !important;
  font-variant-numeric: tabular-nums !important;
}
.stall-rating .rating-count,
.stall-rating-chip .rating-count,
.profile-rating .rating-count,
.seller-rating-row .rating-count {
