.stall-stat-grid .stall-stat[data-stat="totalPurchases"] .stall-stat-val,
.stall-stat-grid .stall-stat[data-stat="lifetimeSales"] .stall-stat-val,
.profile-stat-grid .profile-stat[data-stat="totalSales"] .profile-stat-val,
.profile-stat-grid .profile-stat[data-stat="totalPurchases"] .profile-stat-val {
  font-size: 18px !important;
  line-height: 24px !important;
  font-weight: 500 !important;
