}
.stall-stat-grid .stall-stat[data-stat="totalSales"] .stall-stat-unit,
.stall-stat-grid .stall-stat[data-stat="totalPurchases"] .stall-stat-unit,
.profile-stat-grid .profile-stat[data-stat="totalSales"] .profile-stat-unit,
.profile-stat-grid .profile-stat[data-stat="totalPurchases"] .profile-stat-unit {
  font-size: 12px !important;
  line-height: 16px !important;
  font-weight: 400 !important;
  color: rgba(255, 255, 255, 0.6) !important;
  letter-spacing: 0.4px !important;
  margin-left: 4px !important;
  font-variant-numeric: normal !important;
}
.stall-stat-grid .stall-stat[data-stat="totalPurchases"]::before {
  content: '' !important;
  display: inline-block !important;
  align-self: center !important;
  width: 1px !important;
  height: 24px !important;
  margin-right: 24px !important;
  margin-left: -12px !important;
  background: rgba(255, 255, 255, 0.08) !important;
}
/* END CSFLOAT-1:1 PARITY ship #10504 */
/* CSFLOAT-1:1 PARITY ship #10700 — admin sidebar nav exact metric pass.
   csfloat /admin sidebar uses 240px column, 18px 14px padding, sticky at 56px,
   sections separated by 16px gap, link rows 32px height with 6px 10px padding,
   12px font with 500 weight, active link uses cta blue tint. */
.csfloat-admin-sidebar,
nav.admin-sidebar,
aside.admin-sidebar {
  width: 240px !important;
  padding: 18px 14px !important;
  background: var(--bg) !important;
  border-right: 1px solid var(--line) !important;
