}
.csfloat-admin-sidebar-section-title,
.admin-sidebar-heading {
  font-family: var(--mono) !important;
  font-size: 9px !important;
  font-weight: 700 !important;
  text-transform: uppercase !important;
  letter-spacing: 0.08em !important;
  color: var(--ink-4) !important;
  padding: 6px 10px !important;
  margin: 0 0 4px !important;
}
/* END CSFLOAT-1:1 PARITY ship #10700 */
/* CSFLOAT-1:1 PARITY ship #10701 — admin breadcrumb chrome.
   csfloat breadcrumb: 13px sans, ink-3 ancestors, ink-1 current,
   8px gap, 11px ink-4 separator, 18px bottom margin. */
.admin-breadcrumb,
